// resposta da API pode chegar como 1 item cujo json E o array, ou ja
// separada em N items (depende da versao do n8n) -- cobre os dois casos.
const brutos = $input.all().map((i) => i.json);
const linhas = brutos.length === 1 && Array.isArray(brutos[0]) ? brutos[0] : brutos;
const dataFinal = new Date().toISOString();
const QUANTIDADE = 999; // tem que bater com o 'quantidadeRegistros' do node HTTP Request

function pgVal(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  if (typeof v === 'object') return `'${JSON.stringify(v).replace(/'/g, "''")}'::jsonb`;
  return `'${String(v).replace(/'/g, "''")}'`;
}

if (linhas.length >= QUANTIDADE) {
  console.warn(`[vendedor] pagina cheia (${QUANTIDADE}) neste ciclo -- pode ter cortado registros.`);
}

let sql = 'SELECT 1';
if (linhas.length > 0) {
  const valores = linhas.map((v) =>
    `(${pgVal(v.codigo)}, ${pgVal(v.nome)}, ${pgVal(v.numeroCpf)}, ${pgVal(v.cep)}, ${pgVal(v.email)}, ${pgVal(v.ativo)}, now())`
  ).join(',\n');
  sql = `INSERT INTO vendedores (codigo, nome, numero_cpf, cep, email, ativo, updated_at)
VALUES ${valores}
ON CONFLICT (codigo) DO UPDATE SET
  nome = EXCLUDED.nome,
  numero_cpf = EXCLUDED.numero_cpf,
  cep = EXCLUDED.cep,
  email = EXCLUDED.email,
  ativo = EXCLUDED.ativo,
  updated_at = now();`;
}
sql += `\nUPDATE sync_control SET last_cursor = '${dataFinal}', last_synced_at = now() WHERE entity_name = 'vendedor';`;

return [{ json: { sql, quantidade: linhas.length } }];

