}

if (linhas.length >= QUANTIDADE) {
  console.warn(`[atendimentos] pagina cheia (${QUANTIDADE}) neste ciclo -- pode ter cortado registros.`);
}

let sql = 'SELECT 1';
if (linhas.length > 0) {
  const valores = linhas.map((a) =>
    `(${pgVal(String(a.dataEmissao).slice(0, 10))}, ${pgVal(a.codigoVendedor)}, ${pgVal(a.quantidadeItens)}, ${pgVal(a.quantidadeAtendimentos)})`
  ).join(',\n');
  sql = `INSERT INTO vendas_vendedor_diario (data_emissao, codigo_vendedor, quantidade_itens, quantidade_atendimentos)
VALUES ${valores}
ON CONFLICT (data_emissao, codigo_vendedor) DO UPDATE SET
  quantidade_itens = EXCLUDED.quantidade_itens,
  quantidade_atendimentos = EXCLUDED.quantidade_atendimentos;`;
}
sql += `\nUPDATE sync_control SET last_cursor = '${dataFinal}', last_synced_at = now() WHERE entity_name = 'atendimentos_vendedor';`;

return [{ json: { sql, quantidade: linhas.length } }];

// resposta da API pode chegar como 1 item cujo json E o array, ou ja
// separada em N items (depende da versao do n8n) -- cobre os dois casos.
const brutos = $input.all().map((i) => i.json);
const vendas = brutos.length === 1 && Array.isArray(brutos[0]) ? brutos[0] : brutos;
const dataFinal = new Date().toISOString();
const QUANTIDADE = 999; // tem que bater com o 'quantidadeRegistros' do node HTTP Request

function pgVal(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  if (typeof v === 'object') return `'${JSON.stringify(v).replace(/'/g, "''")}'::jsonb`;
  return `'${String(v).replace(/'/g, "''")}'`;
}

// horaEmissao nao vem sempre como ISO completo -- vendas antigas (ex.
// historico de 2016) mandam so a hora, tipo "00" ou "14". Formato
// desconhecido vira NULL em vez de quebrar o INSERT inteiro do lote.
function horaParaPg(bruto) {
  if (bruto === null || bruto === undefined || bruto === '') return null;
  const s = String(bruto);
  const idxT = s.indexOf('T');
  if (idxT >= 0 && s.length >= idxT + 9) return s.slice(idxT + 1, idxT + 9);
  if (/^\d{2}:\d{2}(:\d{2})?$/.test(s)) return s.length === 5 ? s + ':00' : s;
  if (/^\d{1,2}$/.test(s)) return s.padStart(2, '0') + ':00:00';
  return null;
}

if (vendas.length >= QUANTIDADE) {
  console.warn(`[venda] pagina cheia (${QUANTIDADE}) neste ciclo -- pode ter cortado registros.`);
}

function linhaVenda(v) {
  const dataEmissao = v.dataEmissao ? String(v.dataEmissao).slice(0, 10) : null;
  const horaEmissao = horaParaPg(v.horaEmissao);
  // API manda "S"/null pra venda de ecommerce; a coluna e boolean.
  const vendaEcommerce = v.vendaEcommerce === 'S';
  return `(${pgVal(v.numeroNota)}, ${pgVal(v.numeroNotaOrigem)}, ${pgVal(v.tipoCancelamento)}, ${pgVal(dataEmissao)}, ${pgVal(horaEmissao)}, ${pgVal(v.codigoVendedor)}, ${pgVal(v.codigoCliente)}, ${pgVal(v.entrega)}, ${pgVal(v.pagamentoNaEntrega)}, ${pgVal(v.condicaoPagamento ?? null)}, ${pgVal(v.vlrTroco)}, ${pgVal(v.numeroCupomFiscal)}, ${pgVal(v.numeroNotaFiscal)}, ${pgVal(v.xmlNfe)}, ${pgVal(v.codParceiro)}, ${pgVal(v.codFilial)}, ${pgVal(v.vendaIfood)}, ${pgVal(vendaEcommerce)}, ${pgVal(v.codEcommerce)}, ${pgVal(v.serNotaFiscal)}, ${pgVal(v.modeloVenda)}, ${pgVal(v.dadosEntrega ?? null)}, now())`;
}

const COLUNAS_VENDA = 'numero_nota, numero_nota_origem, tipo_cancelamento, data_emissao, hora_emissao, codigo_vendedor, codigo_cliente, entrega, pagamento_na_entrega, condicao_pagamento, vlr_troco, numero_cupom_fiscal, numero_nota_fiscal, xml_nfe, cod_parceiro, cod_filial, venda_ifood, venda_ecommerce, cod_ecommerce, ser_nota_fiscal, modelo_venda, dados_entrega, updated_at';
const UPDATE_SET_VENDA = `numero_nota_origem = EXCLUDED.numero_nota_origem,
  tipo_cancelamento = EXCLUDED.tipo_cancelamento,
  data_emissao = EXCLUDED.data_emissao,
  hora_emissao = EXCLUDED.hora_emissao,
  codigo_vendedor = EXCLUDED.codigo_vendedor,
  codigo_cliente = EXCLUDED.codigo_cliente,
  entrega = EXCLUDED.entrega,
  pagamento_na_entrega = EXCLUDED.pagamento_na_entrega,
  condicao_pagamento = EXCLUDED.condicao_pagamento,
  vlr_troco = EXCLUDED.vlr_troco,
  numero_cupom_fiscal = EXCLUDED.numero_cupom_fiscal,
  numero_nota_fiscal = EXCLUDED.numero_nota_fiscal,
  xml_nfe = EXCLUDED.xml_nfe,
  cod_parceiro = EXCLUDED.cod_parceiro,
  venda_ifood = EXCLUDED.venda_ifood,
  venda_ecommerce = EXCLUDED.venda_ecommerce,
  cod_ecommerce = EXCLUDED.cod_ecommerce,
  modelo_venda = EXCLUDED.modelo_venda,
  dados_entrega = EXCLUDED.dados_entrega,
  updated_at = now()`;

// sem vendas: WHERE FALSE garante RETURNING vazio (0 items pro proximo node),
// em vez de dar erro de sintaxe com VALUES vazio.
let sql = 'SELECT NULL::bigint AS id, NULL::int AS numero_nota, NULL::int AS cod_filial, NULL::text AS ser_nota_fiscal WHERE FALSE';

if (vendas.length > 0) {
  // ser_nota_fiscal nula precisa de um ON CONFLICT diferente --
  // (numero_nota, cod_filial, ser_nota_fiscal) nunca "bate" quando a
  // serie e NULL (Postgres trata cada NULL como distinto de si mesmo),
  // entao cada reprocessamento duplicava a venda inteira em vez de
  // atualizar. Precisa do indice parcial (numero_nota, cod_filial)
  // where ser_nota_fiscal is null -- ver coletor/migracao_coletor.sql.
  const comSerie = vendas.filter((v) => v.serNotaFiscal != null);
  const semSerie = vendas.filter((v) => v.serNotaFiscal == null);

  const codigosClientes = [...new Set(vendas.map((v) => v.codigoCliente).filter((c) => c != null))];
  const codigosVendedores = [...new Set(vendas.map((v) => v.codigoVendedor).filter((c) => c != null))];
  let stubsSql = '';
  if (codigosClientes.length > 0) {
    stubsSql += `INSERT INTO clientes (codigo) VALUES ${codigosClientes.map((c) => `(${pgVal(c)})`).join(',\n')} ON CONFLICT (codigo) DO NOTHING;\n`;
  }
  if (codigosVendedores.length > 0) {
    stubsSql += `INSERT INTO vendedores (codigo, nome) VALUES ${codigosVendedores.map((c) => `(${pgVal(c)}, '(pendente sincronizacao)')`).join(',\n')} ON CONFLICT (codigo) DO NOTHING;\n`;
  }

  let insertsSql = '';
  if (comSerie.length > 0) {
    insertsSql += `INSERT INTO vendas (${COLUNAS_VENDA})
VALUES ${comSerie.map(linhaVenda).join(',\n')}
ON CONFLICT (numero_nota, cod_filial, ser_nota_fiscal) DO UPDATE SET
  ${UPDATE_SET_VENDA}
RETURNING id, numero_nota, cod_filial, ser_nota_fiscal;\n`;
  }
  if (semSerie.length > 0) {
    insertsSql += `INSERT INTO vendas (${COLUNAS_VENDA})
VALUES ${semSerie.map(linhaVenda).join(',\n')}
ON CONFLICT (numero_nota, cod_filial) WHERE ser_nota_fiscal IS NULL DO UPDATE SET
  ${UPDATE_SET_VENDA}
RETURNING id, numero_nota, cod_filial, ser_nota_fiscal;\n`;
  }

  sql = stubsSql + insertsSql;
}

const vendasComItens = vendas.map((v) => ({
  numeroNota: v.numeroNota,
  codFilial: v.codFilial,
  serNotaFiscal: v.serNotaFiscal,
  itens: v.itens || [],
}));

return [{ json: { sql, vendasComItens, cursorNovo: dataFinal } }];

// input direto: linhas RETURNING (id, numero_nota, cod_filial, ser_nota_fiscal) do node anterior.
// pode vir vazio se nenhuma venda foi upsertada neste ciclo.
const retornados = $input.all().map((item) => item.json);

// .first() em vez de .item: 'Mapear vendas' sempre emite exatamente 1 item
// (mesmo com 0 vendas), mas quando o RETURNING deste ciclo vem vazio o node
// Postgres anterior nao emite nenhum item de saida -- sem item 'atual', o
// pareamento automatico do .item quebra ('Paired item data ... unavailable').
// .first() busca o item direto no node de origem, sem depender desse
// pareamento.
const origem = $('Mapear vendas').first().json;
const vendasComItens = origem.vendasComItens || [];
const cursorNovo = origem.cursorNovo;

function pgVal(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  if (typeof v === 'object') return `'${JSON.stringify(v).replace(/'/g, "''")}'::jsonb`;
  return `'${String(v).replace(/'/g, "''")}'`;
}

// chave natural pra casar RETURNING <-> venda original (nota+filial+serie)
function chave(numeroNota, codFilial, serNotaFiscal) {
  return `${numeroNota}|${codFilial ?? ''}|${serNotaFiscal ?? ''}`;
}

const idPorChave = new Map(
  retornados
    .filter((r) => r.id != null)
    .map((r) => [chave(r.numero_nota, r.cod_filial, r.ser_nota_fiscal), r.id])
);

const linhasItens = [];
const codigosVendedoresItens = new Set();
let vendasSemId = 0;
for (const venda of vendasComItens) {
  const vendaId = idPorChave.get(chave(venda.numeroNota, venda.codFilial, venda.serNotaFiscal));
  if (!vendaId) { vendasSemId += 1; continue; } // nao deveria acontecer -- pula em vez de quebrar o lote inteiro
  for (const [indice, item] of (venda.itens || []).entries()) {
    // vendaComDesconto na API real e NUMBER (valor com desconto), mas
    // venda_itens.venda_com_desconto no schema atual e BOOLEAN.
    // Mapeamento provisorio -- ver coletor/migracao_coletor.sql.
    const vendaComDescontoBool = item.vendaComDesconto != null && item.vendaComDesconto !== item.valorTotalLiquido;
    if (item.codigoVendedor != null) codigosVendedoresItens.add(item.codigoVendedor);
    linhasItens.push(
      `(${pgVal(vendaId)}, ${pgVal(item.codigoProduto)}, ${pgVal(item.codigoVendedor)}, ${pgVal(item.quantidadeProdutos)}, ${pgVal(item.valorTotalBruto)}, ${pgVal(item.valorTotalLiquido)}, ${pgVal(item.valorTotalCusto)}, ${pgVal(item.parceiro)}, ${pgVal(item.codigoMedico)}, ${pgVal(item.codBarras)}, ${pgVal(item.numSequencial ?? indice + 1)}, ${pgVal(item.prcComissao)}, ${pgVal(item.vlrDesconto)}, ${pgVal(item.vlrUnitario)}, ${pgVal(item.vlrCustoAquisicao)}, ${pgVal(item.vlrCustoProduto)}, ${pgVal(item.tabelaDesconto)}, ${pgVal(item.prcDesconto)}, ${pgVal(item.prcDescontoMax)}, ${pgVal(vendaComDescontoBool)})`
    );
  }
}
if (vendasSemId > 0) {
  console.warn(`[venda] ${vendasSemId} venda(s) sem id retornado -- itens dela(s) nao foram gravados neste ciclo.`);
}

// Casar item por item via ON CONFLICT (venda_id, num_sequencial) com
// num_sequencial sintetizado pela posicao no array nao funciona: a
// Trier nao garante que a ordem dos itens de uma nota seja a mesma
// entre chamadas diferentes, entao reprocessar uma venda ja
// sincronizada podia sintetizar um num_sequencial diferente pro mesmo
// item fisico e duplica-lo em vez de atualizar (achado em producao:
// 28.643 itens duplicados, 30,5% da tabela -- ver migracao_coletor.sql
// item 5). Em vez disso: apaga todos os itens das vendas deste ciclo
// antes de reinserir os itens atuais -- imune a ordem.
//
// NOTA: isso apaga em cascata qualquer venda_item_receitas anexada a
// um item dessas vendas (FK on delete cascade). Sem uso real dessa
// feature em producao ainda -- se passar a ter, precisa capturar e
// reanexar a receita ao item novo antes deste delete.
const vendaIdsDoLote = [...idPorChave.values()];
let deleteSql = '';
if (vendaIdsDoLote.length > 0) {
  deleteSql = `DELETE FROM venda_itens WHERE venda_id IN (${vendaIdsDoLote.map(pgVal).join(', ')});\n`;
}

let sql = deleteSql || 'SELECT 1';
if (linhasItens.length > 0) {
  // mesmo motivo do stub em 'Mapear vendas': item pode ter um vendedor
  // diferente do vendedor da nota, e a FK de venda_itens.codigo_vendedor
  // pode nao ter sido satisfeita ainda por esse outro codigo.
  let stubsSqlItens = '';
  if (codigosVendedoresItens.size > 0) {
    stubsSqlItens = `INSERT INTO vendedores (codigo, nome) VALUES ${[...codigosVendedoresItens].map((c) => `(${pgVal(c)}, '(pendente sincronizacao)')`).join(',\n')} ON CONFLICT (codigo) DO NOTHING;\n`;
  }
  sql = deleteSql + stubsSqlItens + `INSERT INTO venda_itens (venda_id, codigo_produto, codigo_vendedor, quantidade_produtos, valor_total_bruto, valor_total_liquido, valor_total_custo, parceiro, codigo_medico, cod_barras, num_sequencial, prc_comissao, vlr_desconto, vlr_unitario, vlr_custo_aquisicao, vlr_custo_produto, tabela_desconto, prc_desconto, prc_desconto_max, venda_com_desconto)
VALUES ${linhasItens.join(',\n')};`;
}

sql += `\nUPDATE sync_control SET last_cursor = '${cursorNovo}', last_synced_at = now() WHERE entity_name = 'venda';`;

return [{ json: { sql, quantidadeItens: linhasItens.length } }];
